const v = input || {};
const NL = String.fromCharCode(10);

function pick(key) {
  const raw = v[key];
  if (raw === undefined || raw === null || String(raw).trim() === "") {
    return `[MISSING: ${key}]`;
  }
  return String(raw).trim();
}

function toHex(value) {
  return Buffer.from(String(value || ""), "utf8").toString("hex").toUpperCase();
}

function makePdfBase64(text) {
  const lines = String(text || "").split(NL).slice(0, 220);
  const stream = ["BT", "/F1 11 Tf", "50 790 Td"];
  for (let i = 0; i < lines.length; i += 1) {
    const lineHex = toHex(lines[i].slice(0, 120));
    stream.push(`<${lineHex}> Tj`);
    if (i < lines.length - 1) {
      stream.push("0 -14 Td");
    }
  }
  stream.push("ET");
  const content = stream.join(NL);

  const object1 = ["1 0 obj", "<< /Type /Catalog /Pages 2 0 R >>", "endobj", ""].join(NL);
  const object2 = ["2 0 obj", "<< /Type /Pages /Kids [3 0 R] /Count 1 >>", "endobj", ""].join(NL);
  const object3 = ["3 0 obj", "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>", "endobj", ""].join(NL);
  const object4 = ["4 0 obj", "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>", "endobj", ""].join(NL);
  const object5 = ["5 0 obj", `<< /Length ${Buffer.byteLength(content, "utf8")} >>`, "stream", content, "endstream", "endobj", ""].join(NL);

  const objects = [null, object1, object2, object3, object4, object5];

  let pdf = ["%PDF-1.4", ""].join(NL);
  const offsets = [0];
  for (let i = 1; i < objects.length; i += 1) {
    offsets[i] = Buffer.byteLength(pdf, "utf8");
    pdf += objects[i];
  }

  const xrefOffset = Buffer.byteLength(pdf, "utf8");
  pdf += ["xref", "0 6", "0000000000 65535 f "].join(NL) + NL;
  for (let i = 1; i < offsets.length; i += 1) {
    pdf += `${String(offsets[i]).padStart(10, "0")} 00000 n ` + NL;
  }
  pdf += ["trailer", "<< /Size 6 /Root 1 0 R >>", "startxref", String(xrefOffset), "%%EOF"].join(NL);
  return Buffer.from(pdf, "utf8").toString("base64");
}

const agreement = [
  "SERVICE AGREEMENT",
  "",
  `This Service Agreement is made between ${pick("provider_name")} and ${pick("client_name")}.`,
  "",
  "1) Services",
  `Provider will deliver the following services: ${pick("service_name")}.`,
  "",
  "2) Term",
  `Start Date: ${pick("start_date")}`,
  `End Date: ${pick("end_date")}`,
  "",
  "3) Fees and Payment",
  `Client agrees to pay ${pick("currency")} ${pick("fee_amount")}.`,
  `Payment Terms: ${pick("payment_terms")}.`,
  "",
  "4) Confidentiality",
  "Both parties agree to keep confidential information private and use it only for this engagement.",
  "",
  "5) Governing Law",
  `This Agreement is governed by the laws of ${pick("jurisdiction")}.`,
  "",
  "6) Special Terms",
  `${pick("special_terms")}`,
  "",
  "7) Signatures",
  `Provider: ${pick("provider_name")}`,
  `Client: ${pick("client_name")}`,
  `Client Email: ${pick("client_email")}`
].join(NL);

const agreementTitle = `Agreement - ${pick("client_name")}`;
const fileName = `${agreementTitle.replace(/[^a-zA-Z0-9_-]+/g, "_")}.pdf`;
const agreementPdfBase64 = makePdfBase64(agreement);

return {
  agreement_text: agreement,
  agreement_title: agreementTitle,
  agreement_file_name: fileName,
  agreement_pdf_base64: agreementPdfBase64,
  generated_at: new Date().toISOString()
};
